function _mpmCenterBodyHtml() {
  const activeQuery = _mpmActiveQueryTab();
  const activeTable = _mpmActiveTableTab();
  return activeQuery
    ? `<div class="mpm-center__query">${_mpmConsoleHtml(activeQuery)}</div>`
    : activeTable
      ? `<div class="mpm-center__table">${_mpmTableTabHtml(activeTable)}</div>`
      : _mpmObjectsHtml();
}

function _mpmStatusInner() {
  const files = _mpmState.files;
  const conn = _mpmSelectedConn();
  const objectCount = _mpmObjectList().length;
  const connCount = (Array.isArray(files) ? files.length : 0) + _mpmState.savedConns.length;
  return `
    <span>${Array.isArray(files) ? `${connCount} 个连接` : "扫描中…"}</span>
    ${conn && _mpmState.centerTab === "objects" ? `<span>${objectCount} 个对象</span>` : ""}
    ${conn ? `<span class="is-mono" title="${_escAttr(conn.url)}">${_escHtml(conn.kind === "saved" ? String(conn.url).replace(/:\/\/([^:@/]+):[^@]+@/, "://$1:••••@") : conn.url)}</span>` : ""}
    <i></i>
    <span class="mp-statusbar__brand">Michael Premium</span>`;
}

// 功能区/连接树里「表/视图/函数/查询」的高亮同步（不重建 DOM，纯 class 切换）。
function _mpmUpdateCatActive(root) {
  const cat = _mpmState.category;
  const onObjects = _mpmState.centerTab === "objects";
  root.querySelectorAll("[data-mpm-act]").forEach((b) => {
    const a = b.getAttribute("data-mpm-act") || "";
    if (!a.startsWith("cat-") && a !== "new-query") return;
    let on = false;
    if (a === "cat-tables") on = onObjects && cat === "tables";
    else if (a === "cat-views") on = onObjects && cat === "views";
    else if (a === "cat-fx") on = onObjects && cat === "fx";
    else if (a === "new-query") on = _mpmState.centerTab.startsWith("q:");
    b.classList.toggle("is-active", on);
  });
}

function _mpmAfterRender() {
  if (!_mpManagerEl) return;
  if (_mpmState.connFilter) _mpmFilterDom("[data-mpm-conn]", _mpmState.connFilter);
  if (_mpmState.objFilter) { _mpmFilterDom("[data-mpm-obj]", _mpmState.objFilter); _mpmFilterDom("[data-mpm-obj-fn]", _mpmState.objFilter); }
  const sqlMount = _mpManagerEl.querySelector("[data-mpm-sql-mount]");
  const activeQuery = _mpmActiveQueryTab();
  if (sqlMount && activeQuery) _mpmMountSqlEditor(activeQuery, sqlMount);
}

function _mpmRender() {
  if (!_mpManagerEl) return;
  _mpManagerEl.innerHTML = `
    <div class="mpm-sheet" role="dialog" aria-modal="true" aria-label="Michael Premium 数据库工具">
      ${_mpmRibbonHtml()}
      <div class="mpm-main">
        <aside class="mpm-tree">
          <div class="mpm-tree__list" data-mpm-list>${_mpmTreeHtml()}</div>
          <label class="mp-side-search mpm-tree__search">${_dbUiIconSvg("search")}<input data-mpm-conn-filter placeholder="搜索连接" aria-label="搜索连接" value="${_escAttr(_mpmState.connFilter || "")}" /></label>
        </aside>
        <section class="mpm-center">
          <div class="mpm-center__tabs">${_mpmCenterTabsInner()}</div>
          <div class="mpm-center__body">${_mpmCenterBodyHtml()}</div>
        </section>
        <aside class="mpm-info">${_mpmInfoHtml()}</aside>
      </div>
      <footer class="mpm-status">${_mpmStatusInner()}</footer>
      ${_mpmDialogHtml()}
    </div>`;
  _mpmAfterRender();
}

// 局部刷新：只重建中间区 + 信息栏 + 状态栏 + 高亮，保留最重的连接树不动——
// 切「表/视图/函数/查询」和切标签页都走这里，消除整窗重建的闪烁。
function _mpmRenderCenter() {
  const sheet = _mpManagerEl?.querySelector(".mpm-sheet");
  if (!sheet || !sheet.querySelector(".mpm-tree")) { _mpmRender(); return; }
  const center = sheet.querySelector(".mpm-center");
  if (center) center.innerHTML = `<div class="mpm-center__tabs">${_mpmCenterTabsInner()}</div><div class="mpm-center__body">${_mpmCenterBodyHtml()}</div>`;
  const infoEl = sheet.querySelector(".mpm-info");
  if (infoEl) infoEl.innerHTML = _mpmInfoHtml();
  const statusEl = sheet.querySelector(".mpm-status");
  if (statusEl) statusEl.innerHTML = _mpmStatusInner();
  _mpmUpdateCatActive(sheet);
  _mpmAfterRender();
}

function _mpmRenderCenterIfOpen() {
  if (_mpManagerEl && !_mpManagerEl.hidden) _mpmRenderCenter();
}
// ---- chat-image lightbox (click to view at full / natural size) ----
let _imgLightboxEl = null;
// 生图的 data_url 按绝对路径缓存：design_board 渲染时优先用它（base64 直接显示，跟顶部
// genimage 预览同一条可靠路径），绕开 Tauri asset 协议——.wardrobe 这类隐藏目录(点开头)
// 的 glob scope 常匹配不上 → webview 拒载 → 图空白。容量上限防内存涨。
const _genImgDataUrls = new Map();
function _cacheGenImg(absPath, dataUrl) {
  if (!absPath || !dataUrl) return;
  try {
    if (_genImgDataUrls.size > 24) _genImgDataUrls.delete(_genImgDataUrls.keys().next().value);
    _genImgDataUrls.set(absPath, dataUrl);
  } catch {}
}
// visual_compare 用：把【目标设计图】和【实时实现截图】并排拼成一张，回传给模型逐项比对、做到像素级还原。
async function _composeCompare(designUrl, liveUrl) {
  const load = (src) => new Promise((resolve, reject) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = reject; im.src = src; });
  const [a, b] = await Promise.all([load(designUrl), load(liveUrl)]);
  const H = 920, gap = 28, labelH = 40;
  const aw = Math.max(1, Math.round(a.width * H / Math.max(1, a.height)));
  const bw = Math.max(1, Math.round(b.width * H / Math.max(1, b.height)));
  const cv = document.createElement("canvas");
  cv.width = aw + bw + gap; cv.height = H + labelH;
  const ctx = cv.getContext("2d");
  ctx.fillStyle = "#0b0d12"; ctx.fillRect(0, 0, cv.width, cv.height);
  ctx.drawImage(a, 0, labelH, aw, H);
  ctx.drawImage(b, aw + gap, labelH, bw, H);
  ctx.fillStyle = "#7dd3fc"; ctx.font = "600 22px -apple-system,system-ui,sans-serif"; ctx.textBaseline = "middle";
  ctx.fillText("◀ 目标设计 DESIGN", 10, labelH / 2);
  ctx.fillStyle = "#fca5a5"; ctx.fillText("你的实现 LIVE ▶", aw + gap + 10, labelH / 2);
  return cv.toDataURL("image/jpeg", 0.85);
}
function showImageLightbox(src) {
  if (!src) return;
  if (!_imgLightboxEl) {
    _imgLightboxEl = document.createElement("div");
    _imgLightboxEl.style.cssText = "position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:99999;display:flex;align-items:center;justify-content:center;cursor:zoom-out;opacity:0;transition:opacity .12s ease;backdrop-filter:blur(4px)";
    _imgLightboxEl.innerHTML = `<img style="max-width:96vw;max-height:94vh;object-fit:contain;border-radius:6px;box-shadow:0 12px 48px rgba(0,0,0,.6);user-select:none" /><button type="button" style="position:absolute;top:18px;right:22px;width:36px;height:36px;border-radius:50%;border:0;background:rgba(255,255,255,.12);color:#fff;font-size:22px;line-height:1;cursor:pointer;backdrop-filter:blur(8px)" aria-label="关闭">×</button><div style="position:absolute;bottom:18px;left:50%;transform:translateX(-50%);color:rgba(255,255,255,.6);font-size:12px;pointer-events:none">点击任意位置 / 按 Esc 关闭</div>`;
    document.body.appendChild(_imgLightboxEl);
    // 关闭：必须显式 display:none——元素内联有 display:flex，会盖过 [hidden] 的 display:none，
    // 否则只是透明了、却仍是个全屏 z-index 99999 捕获所有点击的覆盖层 → 整个 UI 卡死动不了。
    const close = () => { _imgLightboxEl.style.opacity = "0"; _imgLightboxEl.style.pointerEvents = "none"; setTimeout(() => { _imgLightboxEl.style.display = "none"; }, 130); };
    _imgLightboxEl.addEventListener("click", close);
    document.addEventListener("keydown", (e) => { if (e.key === "Escape" && _imgLightboxEl && _imgLightboxEl.style.display !== "none") close(); });
  }
  _imgLightboxEl.querySelector("img").src = src;
  _imgLightboxEl.style.display = "flex";
  _imgLightboxEl.style.pointerEvents = "";
  requestAnimationFrame(() => { _imgLightboxEl.style.opacity = "1"; });
}

// ---- markdown preview ----
let _mdPreviewEl = null;
let _mdThumbEl = null;
let _mdPreviewDisposable = null;
let _mdPreviewOpen = false;
let _mdActiveModel = null;

function _createMdElements() {
  if (_mdPreviewEl) return;

  // preview pane
  _mdPreviewEl = document.createElement("div");
  _mdPreviewEl.className = "md-preview";
  _mdPreviewEl.hidden = true;
  const header = document.createElement("div");
  header.className = "md-preview__header";
  header.innerHTML = `<span class="md-preview__title">Markdown 预览</span>
    <button class="md-preview__close" title="关闭预览 ${_escAttr(shortcutLabel("mod+."))}">✕</button>`;
  _mdPreviewEl.appendChild(header);
  const body = document.createElement("div");
  body.className = "md-preview__body";
  _mdPreviewEl.appendChild(body);
  editorContainer.appendChild(_mdPreviewEl);
  header.querySelector(".md-preview__close").addEventListener("click", () => _toggleMdPreview(false));

  // thumbnail strip
  _mdThumbEl = document.createElement("div");
  _mdThumbEl.className = "md-thumb";
  _mdThumbEl.hidden = true;
  _mdThumbEl.innerHTML = `<div class="md-thumb__mini"></div>`;
  _mdThumbEl.addEventListener("click", () => _toggleMdPreview(true));
  editorContainer.appendChild(_mdThumbEl);
}

function _toggleMdPreview(open) {
  _mdPreviewOpen = open;
  // preview: show or hide
  if (_mdPreviewEl) _mdPreviewEl.hidden = !open;
  // thumbnail: opposite of preview
  if (_mdThumbEl) _mdThumbEl.hidden = open;
}

function _renderMdThumb() {
  if (!_mdThumbEl || !_mdPreviewEl) return;
  const body = _mdPreviewEl.querySelector(".md-preview__body");
  const mini = _mdThumbEl.querySelector(".md-thumb__mini");
  if (!body || !mini) return;
  mini.textContent = "";
  const clone = body.cloneNode(true);
  clone.className = "md-thumb__content";
  mini.appendChild(clone);
}

function showMarkdownPreview(model) {
  _createMdElements();
  _mdActiveModel = model;
  const body = _mdPreviewEl.querySelector(".md-preview__body");
  function render() {
    renderMarkdownInto(body, model.getValue());
    if (!_mdPreviewOpen) _renderMdThumb();
  }
  render();
  if (_mdPreviewDisposable) _mdPreviewDisposable.dispose();
  // Debounce: re-parsing the WHOLE markdown doc on EVERY keystroke starves the UI thread on a large
  // README — a top cause of "编辑时发烫 / 卡". ~180ms after a typing pause is imperceptible and cheap.
  let _mdT = 0;
  _mdPreviewDisposable = model.onDidChangeContent(() => {
    if (_mdT) clearTimeout(_mdT);
    _mdT = setTimeout(render, 180);
  });
  _toggleMdPreview(false);
}

function hideMarkdownPreview() {
  _mdPreviewOpen = false;
  _mdActiveModel = null;
  if (_mdPreviewEl) _mdPreviewEl.hidden = true;
  if (_mdThumbEl) _mdThumbEl.hidden = true;
  if (_mdPreviewDisposable) { _mdPreviewDisposable.dispose(); _mdPreviewDisposable = null; }
}

// ⌘. to toggle markdown preview
document.addEventListener("keydown", (e) => {
  if ((e.metaKey || e.ctrlKey) && e.key === ".") {
    e.preventDefault();
    if (!_mdActiveModel) return;
    _toggleMdPreview(!_mdPreviewOpen);
    if (!_mdPreviewOpen) _renderMdThumb();
  }
});

// ---- 整体界面缩放（Cmd/Ctrl + = / - / 0）：代码编辑器和所有 UI 一起缩放 ----
const _UI_ZOOM_KEY = "michael-ide.ui-zoom";
let _uiZoom = (() => {
  const v = Number(localStorage.getItem(_UI_ZOOM_KEY));
  return v >= 0.5 && v <= 2 ? v : 1;
})();
async function _applyUiZoom(factor, { toast = true } = {}) {
  _uiZoom = Math.min(2, Math.max(0.5, Math.round(factor * 100) / 100));
  try { localStorage.setItem(_UI_ZOOM_KEY, String(_uiZoom)); } catch {}
  let applied = false;
  if (inTauri) {
    try {
      const { getCurrentWebview } = await import("@tauri-apps/api/webview");
      await getCurrentWebview().setZoom(_uiZoom);
      applied = true;
    } catch { /* 平台不支持 setZoom → 回退 CSS zoom */ }
  }
  if (!applied) {
    document.documentElement.style.zoom = _uiZoom === 1 ? "" : String(_uiZoom);
  }
  // 缩放后让所有按可视尺寸排版的组件重新布局（Monaco、分屏编辑器、终端、面板）
  requestAnimationFrame(() => {
    try { monacoEditor?.layout?.(); } catch {}
    try { splitState?.editor?.layout?.(); } catch {}
    try { window.dispatchEvent(new Event("resize")); } catch {}
  });
  if (toast) showToast(`界面缩放 ${Math.round(_uiZoom * 100)}%`);
}
if (_uiZoom !== 1) _applyUiZoom(_uiZoom, { toast: false });
document.addEventListener("keydown", (e) => {
  if (!(e.metaKey || e.ctrlKey) || e.altKey || e.shiftKey && !["+", "="].includes(e.key)) return;
  const k = e.key;
  if (k === "=" || k === "+") { e.preventDefault(); _applyUiZoom(_uiZoom + 0.1); }
  else if (k === "-") { e.preventDefault(); _applyUiZoom(_uiZoom - 0.1); }
  else if (k === "0") { e.preventDefault(); _applyUiZoom(1); }
}, true);

function updateBreadcrumb(path) {
  const bc = $("breadcrumb");
  if (!path) { bc.hidden = true; return; }
  bc.hidden = false;
  bc.innerHTML = "";
  const rel = rootPath ? path.replace(rootPath, "").replace(/^\//, "") : path;
  const segments = rel.split("/").filter(Boolean);
  segments.forEach((seg, i) => {
    if (i > 0) {
      const sep = document.createElement("span");
      sep.className = "breadcrumb__sep";
      sep.textContent = "›";
      bc.appendChild(sep);
    }
    const el = document.createElement("span");
    el.className = "breadcrumb__seg";
    el.textContent = seg;
    if (i < segments.length - 1) {
      const partial = rootPath + "/" + segments.slice(0, i + 1).join("/");
      el.addEventListener("click", () => revealInTree(partial));
    }
    bc.appendChild(el);
  });
}

function revealInTree(path) {
  const item = document.querySelector(`.tree-item[data-path="${CSS.escape(path)}"]`);
  if (item) {
    item.scrollIntoView({ block: "center" });
    item.classList.add("flash");
    setTimeout(() => item.classList.remove("flash"), 600);
  }
}

const pinnedTabs = new Set();
function togglePinTab(path) {
  if (pinnedTabs.has(path)) pinnedTabs.delete(path);
  else pinnedTabs.add(path);
  renderTabs();
  scheduleSaveSession(); // persist the pin now, not only when some other action saves
}

async function closeFile(path, { force = false } = {}) {
  path = _coherentFilePath(path);
  const f = openFiles.get(path);
  if (!f) return true;
  if (pinnedTabs.has(path) && !force) return false; // pinned tabs cannot be closed manually
  if (force) pinnedTabs.delete(path);
  // Don't silently lose unsaved edits on tab close — the 800ms autosave debounce may
  // not have fired yet, and the hot-exit backup only covers app close. Save to disk
  // first; if that fails, stash a recoverable backup + warn (never silently drop).
  if (f.dirty && f.model && !f.isImage && !f.isVideo && !f.isInspection) {
    let snapshot = "";
    try { snapshot = f.model.getValue(); } catch {}
    try {
      await _writeOpenFileSnapshot(path, snapshot);
      if (f.model.getValue() !== snapshot) {
        markDirty(path, true);
        scheduleAutoSave(path);
        showToast(`未关闭 ${f.name}：保存期间仍有新输入，已继续保存最新内容`);
        return false;
      }
      markDirty(path, false);
    } catch (e) {
      let latest = snapshot;
      try { latest = f.model.getValue(); } catch {}
      try {
        const bak = JSON.parse(localStorage.getItem("michael-ide.unsaved-buffers") || "[]");
        const i = bak.findIndex((b) => b.path === path);
        if (i >= 0) bak[i].content = latest; else bak.push({ path, content: latest });
        localStorage.setItem("michael-ide.unsaved-buffers", JSON.stringify(bak));
      } catch {}
      try { showToast("⚠ " + (f.name || path) + " 未能保存，已保留标签并备份当前内容"); } catch {}
      return false;
    }
  }
  if (!f.isInspection) lspManager?.didClose(path);
  if (!projectModels.has(path) && f.model) f.model.dispose();
  openFiles.delete(path);
  if (activePath === path) {
    activePath = null;
    const next = [...openFiles.keys()].pop();
    if (next) activate(next);
    else {
      monacoEditor.setModel(monaco.editor.createModel("", "plaintext"));
      hideImagePreview();
      hideVideoPreview();
      hidePdfPreview();
      hideFileInspectionPreview();
      hideMarkdownPreview();
      saveBtn.disabled = true;
      if (runBtn) runBtn.disabled = true;
      const idleTitle = rootPath ? basename(rootPath) + " — Michael IDE" : "Michael IDE";
      $("windowTitle").textContent = idleTitle;
      refreshGutter();
      updateBreadcrumb(null);
    }
  }
  renderTabs();
  syncWelcome();
  return true;
}

async function _closeOpenFilesUnder(path) {
  for (const openPath of [...openFiles.keys()]) {
    if (!_pathIsAtOrUnder(openPath, path)) continue;
    if (!(await closeFile(openPath))) {
      showToast(`无法继续：${openFiles.get(openPath)?.name || openPath} 仍打开或尚未保存`);
      return false;
    }
  }
  return true;
}

async function _closeOpenFilesOutsideRoot(root) {
  root = _normalizeFsPath(root);
  if (!root) return true;
  for (const openPath of [...openFiles.keys()]) {
    if (_pathIsAtOrUnder(openPath, root)) continue;
    // Switching projects means old-project tabs should not survive just because they
    // were pinned. closeFile(force:true) still protects dirty buffers by saving first,
    // and refuses to close if it cannot safely persist/backup the latest text.
    if (!(await closeFile(openPath, { force: true }))) {
      showToast(`无法切换项目：${openFiles.get(openPath)?.name || openPath} 仍打开或尚未保存`);
      return false;
    }
  }
  return true;
}

function _dirtyOpenFileUnder(path) {
  path = _coherentFilePath(path);
  for (const [openPath, file] of openFiles) {
    if (_pathIsAtOrUnder(openPath, path) && file?.dirty) return openPath;
  }
  return "";
}

function closeOtherTabs(keepPath) {
  for (const path of [...openFiles.keys()]) {
    if (path !== keepPath) closeFile(path);
  }
}

function closeTabsToRight(fromPath) {
  const paths = [...openFiles.keys()];
  const idx = paths.indexOf(fromPath);
  if (idx < 0) return;
  for (const path of paths.slice(idx + 1)) closeFile(path);
}

function closeAllTabs() {
  for (const path of [...openFiles.keys()]) closeFile(path);
}

function relativePath(path) {
  if (rootPath && path.startsWith(rootPath + "/")) return path.slice(rootPath.length + 1);
  return basename(path);
}

function openTabContextMenu(x, y, path) {
  const isPinned = pinnedTabs.has(path);
  renderMenuAt(x, y, [
    { label: t("tabctx.close"), icon: "i-close", action: () => closeFile(path) },
    { label: t("tabctx.closeOthers"), action: () => closeOtherTabs(path) },
    { label: t("tabctx.closeRight"), action: () => closeTabsToRight(path) },
    { label: t("tabctx.closeAll"), action: () => closeAllTabs() },
    { sep: true },
    { label: isPinned ? t("tabctx.unpin") : t("tabctx.pin"), action: () => togglePinTab(path) },
    { label: t("tabctx.reveal"), icon: "i-files", action: () => _revealPathInSystemExplorer(path) },
    { sep: true },
    { label: t("tabctx.copyPath"), icon: "i-copy", action: () => copyText(path) },
    { label: t("tabctx.copyRelPath"), icon: "i-copy", action: () => copyText(relativePath(path)) },
  ]);
}

function markDirty(path, dirty) {
  const f = openFiles.get(path);
  if (!f || f.dirty === dirty) return;
  f.dirty = dirty;
  if (path === activePath) saveBtn.disabled = !dirty;
  const tabEl = tabsEl.querySelector(`[data-path="${CSS.escape(path)}"]`);
  if (tabEl) {
    if (dirty) tabEl.classList.add("dirty");
    else tabEl.classList.remove("dirty");
  } else {
    renderTabs();
  }
}

// Update a clean open editor after a known disk write. Dirty buffers are never
// replaced: they may contain user input that has not reached disk yet.
function _applyDiskContentToOpenFile(path, content) {
  path = _coherentFilePath(path);
  const f = openFiles.get(path);
  const opening = _openingFiles.get(path);
  if (opening && !f) {
    opening.diskContent = content;
    opening.hasDiskContent = true;
    opening.externalDeleted = false;
    opening.diskVersion = (opening.diskVersion || 0) + 1;
    return { state: "opening-updated" };
  }
  if (!f || !f.model || f.isImage || f.isVideo || f.isPdf || f.isInspection) {
    // Preloaded project models also feed Monaco diagnostics even without an open
    // tab. Keep them coherent or verification can inspect the code from before the
    // Agent write and report a false pass/failure.
    let model = null;
    try { if (projectModels.has(path)) model = monaco.editor.getModel(monaco.Uri.file(path)); } catch {}
    if (!model) return { state: "closed" };
    if (_setModelValueProgrammatically(model, content)) lspManager?.didChange(path, model);
    lspManager?.didSave(path, model);
    return { state: "project-model-updated" };
  }
  if (f.dirty) {
    f.externalConflict = true;
    return { state: "conflict" };
  }
  const model = f.model;
  const viewState = path === activePath ? monacoEditor.saveViewState() : null;
  if (_setModelValueProgrammatically(model, content)) {
    if (viewState) monacoEditor.restoreViewState(viewState);
    lspManager?.didChange(path, model);
  }
  f.diskContent = content;
  f.externalConflict = false;
  f.externalDeleted = false;
  markDirty(path, false);
  lspManager?.didSave(path, model);
  return { state: "updated" };
}

function _openFileWriteConflict(path) {
  path = _coherentFilePath(path);
  const f = openFiles.get(path);
  return !!(f && f.model && f.dirty);
}

async function _commitDiskTextIfUnchanged(path, expectedContent, content) {
  path = _coherentFilePath(path);
  if (_openFileWriteConflict(path)) throw new Error("编辑器有尚未保存的用户改动，已阻止覆盖");
  await backend.writeTextFileIfUnchanged(path, expectedContent, content);
  const sync = _applyDiskContentToOpenFile(path, content);
  if (sync.state !== "conflict") return path;
  let rolledBack = false;
  try {
    if (expectedContent == null) await backend.deleteTextFileIfUnchanged(path, content);
    else await backend.writeTextFileIfUnchanged(path, content, expectedContent);
    rolledBack = true;
  } catch {}
  const open = openFiles.get(path);
  if (rolledBack && open) open.externalConflict = false;
  throw new Error(rolledBack
    ? "写入期间用户继续编辑，本次写入已撤销"
    : "写入期间编辑器和磁盘都发生变化，已保留用户缓冲区");
}

// Serialize editor saves per path and use the last known disk snapshot as the CAS
// expectation. A stale buffer can therefore never silently overwrite an Agent,
// terminal, Git, or second-window change.
const _pendingEditorWrites = new Map();
const _externalSyncGeneration = new Map();
async function _writeOpenFileSnapshot(path, snapshot) {
  path = _coherentFilePath(path);
  const f = openFiles.get(path);
  if (!f || !f.model) throw new Error("文件已关闭");
  // Re-check after every wait. If B and C both arrived while A was saving, B
  // installs its operation before yielding, so C observes and waits for B too.
  while (f._savePromise) {
    try { await f._savePromise; } catch {}
  }
  const expected = typeof f.diskContent === "string"
    ? f.diskContent
    : await backend.readTextFile(path);
  const op = backend.writeTextFileIfUnchanged(path, expected, snapshot);
  const pending = { content: snapshot, op };
  _pendingEditorWrites.set(path, pending);
  f._savePromise = op;
  try {
    await op;
    f.diskContent = snapshot;
    f.externalConflict = false;
    f.externalDeleted = false;
  } finally {
    if (f._savePromise === op) f._savePromise = null;
    if (_pendingEditorWrites.get(path) === pending) _pendingEditorWrites.delete(path);
  }
}

function _isMissingFileError(error) {
  return /No such file or directory|not found|does not exist|cannot find|ENOENT|os error 2|找不到(?:指定的)?文件|文件不存在/i.test(String(error?.message || error || ""));
}

function _dropProjectModel(path) {
  path = _coherentFilePath(path);
  projectModels.delete(path);
  if (openFiles.has(path)) return;
  try {
    const model = monaco.editor.getModel(monaco.Uri.file(path));
    if (model) model.dispose();
  } catch {}
}

async function _syncOpenFilesFromDisk(paths, source = "外部程序") {
  const changedPaths = [...new Set((paths || []).map(_coherentFilePath).filter(Boolean))];
  const trackedPaths = [...new Set([...openFiles.keys(), ..._openingFiles.keys()])];
  const targets = trackedPaths.filter((path) => changedPaths.some((changedPath) => _pathIsAtOrUnder(path, changedPath)));
  for (const path of targets) {
    const initialFile = openFiles.get(path);
    const initialOpening = _openingFiles.get(path);
    if ((!initialFile || !initialFile.model || initialFile.isImage || initialFile.isVideo || initialFile.isPdf || initialFile.isInspection) && !initialOpening) continue;
    const generation = (_externalSyncGeneration.get(path) || 0) + 1;
    _externalSyncGeneration.set(path, generation);
    const diskContentBeforeRead = initialFile?.diskContent;
    const openingVersionBeforeRead = initialOpening?.diskVersion || 0;
    let disk;
    let readError = null;
    try { disk = await backend.readTextFile(path); } catch (error) { readError = error; }
    // A newer save/Agent sync won while this asynchronous read was in flight.
    // Discard the stale result; its own watcher event (or immediate Agent sync)
    // already owns the newer generation.
    if (_externalSyncGeneration.get(path) !== generation) continue;
    const opening = _openingFiles.get(path);
    const f = openFiles.get(path);
    const openingStillCurrent = !!initialOpening && opening === initialOpening
      && (initialOpening.diskVersion || 0) === openingVersionBeforeRead;
    const transitionedOpeningFileCurrent = !!f && !initialFile && !!initialOpening
      && initialOpening.openedFile === f
      && (initialOpening.diskVersion || 0) === openingVersionBeforeRead
      && f.diskContent === initialOpening.finalDiskContent;
    const fileStillCurrent = initialFile
      ? (f === initialFile && f.diskContent === diskContentBeforeRead)
      : transitionedOpeningFileCurrent;
    if (!openingStillCurrent && !fileStillCurrent) continue;
    if (readError) {
      if (!_isMissingFileError(readError) || _pendingEditorWrites.has(path)) continue;
      if (openingStillCurrent) {
        initialOpening.externalDeleted = true;
        initialOpening.diskVersion = openingVersionBeforeRead + 1;
      }
      if (!fileStillCurrent) continue;
      if (f.dirty) {
        if (!f.externalDeleted) showToast(`⚠️ ${source}删除了 ${f.name}；已保留你的未保存内容，未重新创建或覆盖磁盘`);
        f.externalConflict = true;
        f.externalDeleted = true;
        continue;
      }
      _dropProjectModel(path);
      if (await closeFile(path, { force: true })) showToast(`${f.name} 已被${source}删除，已关闭旧标签`);
      continue;
    }
    if (openingStillCurrent) {
      initialOpening.diskContent = disk;
      initialOpening.hasDiskContent = true;
      initialOpening.externalDeleted = false;
      initialOpening.diskVersion = openingVersionBeforeRead + 1;
    }
    if (!fileStillCurrent) continue;
    f.externalDeleted = false;
    const pending = _pendingEditorWrites.get(path);
    if (pending && disk === pending.content) {
      f.diskContent = disk;
      continue;
    }
    if (disk === f.diskContent) continue;
    if (f.dirty) {
      if (!f.externalConflict) showToast(`⚠️ ${source}修改了 ${f.name}；已保留你的未保存内容，未自动覆盖`);
      f.externalConflict = true;
      continue;
    }
    _applyDiskContentToOpenFile(path, disk);
  }

  // A preloaded Monaco model can exist without an open tab. Drop it when its
  // exact file is externally deleted so diagnostics never inspect stale code.
  const preloadedTargets = [...projectModels].filter((path) => changedPaths.some((changedPath) => _pathIsAtOrUnder(path, changedPath)));
  for (const path of preloadedTargets) {
    if (openFiles.has(path) || _openingFiles.has(path)) continue;
    let model = null;
    let contentBeforeRead = null;
    try {
      model = monaco.editor.getModel(monaco.Uri.file(path));
      if (model) contentBeforeRead = model.getValue();
    } catch {}
    try {
      const disk = await backend.readTextFile(path);
      if (openFiles.has(path) || _openingFiles.has(path) || !projectModels.has(path)) continue;
      if (model && model.getValue() !== contentBeforeRead) continue;
      _applyDiskContentToOpenFile(path, disk);
    } catch (error) {
      if (_isMissingFileError(error) && !openFiles.has(path) && !_openingFiles.has(path)) _dropProjectModel(path);
    }
  }
}

async function _resolveManualSaveConflict(path, file, snapshot, originalError) {
  if (openFiles.get(path) !== file || file.model.getValue() !== snapshot) return false;
  let disk = "";
  let missing = false;
  try { disk = await backend.readTextFile(path); }
  catch (error) {
    if (_isMissingFileError(error)) missing = true;
    else {
      showToast(`保存失败：${String(originalError?.message || originalError || error).slice(0, 100)}`);
      return false;
    }
  }
  if (!missing && disk === file.diskContent) {
    showToast(`保存失败：${String(originalError?.message || originalError).slice(0, 100)}`);
    return false;
  }
  file.externalConflict = true;
  file.externalDeleted = missing;
  if (openFiles.get(path) !== file || file.model.getValue() !== snapshot) return false;

  const overwrite = await ioConfirm({
    title: missing ? `${file.name} 已被删除` : `${file.name} 已在磁盘上变化`,
    message: missing
      ? "是否用编辑器中的当前内容重新创建该文件？取消会继续保留未保存内容。"
      : "是否用编辑器中的当前内容明确覆盖磁盘新版本？取消后还可以选择重新载入磁盘。",
    okLabel: missing ? "重新创建" : "覆盖磁盘",
    danger: true,
  });
  if (openFiles.get(path) !== file || file.model.getValue() !== snapshot) {
    showToast(`${file.name} 在确认期间仍有新输入，本次保存已取消`);
    return false;
  }
  if (overwrite) {
    try {
      await backend.writeTextFileIfUnchanged(path, missing ? null : disk, snapshot);
      file.diskContent = snapshot;
      file.externalConflict = false;
      file.externalDeleted = false;
      if (openFiles.get(path) !== file) return false;
      if (file.model.getValue() !== snapshot) {
        markDirty(path, true);
        scheduleAutoSave(path);
        showToast(`${file.name} 在覆盖期间仍有新输入，已继续排队保存最新内容`);
        return false;
      }
      markDirty(path, false);
      lspManager?.didSave(path, file.model);
      if (typeof refreshSymbolIndexFor === "function") { try { refreshSymbolIndexFor(path); } catch {} }
      showToast(t("file.saved", { name: file.name }));
      return true;
    } catch (error) {
      showToast(`覆盖失败：磁盘又发生了变化；编辑器内容仍保留。${String(error?.message || error).slice(0, 80)}`);
      return false;
    }
  }
  if (missing) return false;

  const reload = await ioConfirm({
    title: `重新载入 ${file.name}？`,
    message: "这会丢弃编辑器里尚未保存的冲突内容，并载入磁盘上的最新版本。",
    okLabel: "重新载入",
    danger: true,
  });
  if (!reload || openFiles.get(path) !== file || file.model.getValue() !== snapshot) return false;
  try {
    const latest = await backend.readTextFile(path);
    if (openFiles.get(path) !== file || file.model.getValue() !== snapshot) return false;
    markDirty(path, false);
    _applyDiskContentToOpenFile(path, latest);
    showToast(`已重新载入 ${file.name}`);
  } catch (error) {
    markDirty(path, true);
    showToast(`重新载入失败：${String(error?.message || error).slice(0, 100)}`);
  }
  return false;
}

async function saveActive(path = activePath) {
  if (!path) return false;
  const savingPath = _coherentFilePath(path);
  const f = openFiles.get(savingPath);
  if (!f || !f.model) return false;
  const snapshot = f.model.getValue();
  try {
    await _writeOpenFileSnapshot(savingPath, snapshot);
    if (openFiles.get(savingPath) === f && f.model.getValue() === snapshot) {
      markDirty(savingPath, false);
      lspManager?.didSave(savingPath, f.model);
      showToast(t("file.saved", { name: f.name }));
      refreshBlame();
      // Keep the find_symbol index current — re-extract entries for the saved file.
      if (typeof refreshSymbolIndexFor === "function") { try { refreshSymbolIndexFor(savingPath); } catch {} }
      return true;
    } else if (openFiles.get(savingPath) === f) {
      markDirty(savingPath, true);
      scheduleAutoSave(savingPath);
      showToast(`${f.name} 仍在编辑，已继续排队保存最新内容`);
    }
  } catch (e) {
    f.externalConflict = true;
    return await _resolveManualSaveConflict(savingPath, f, snapshot, e);
  }
  return false;
}

let dragSrcPath = null;

function renderTabs() {
  tabsEl.innerHTML = "";
  for (const [path, f] of openFiles) {
    const tab = document.createElement("div");
    tab.className = "tab" + (path === activePath ? " is-active" : "") + (f.dirty ? " dirty" : "") + (pinnedTabs.has(path) ? " is-pinned" : "");
    tab.draggable = true;
    tab.dataset.path = path;
    tab.innerHTML =
      `${iconImg(fileIconUrl(f.name))}<span class="label"></span>` +
      `<span class="x" title="Close"><span class="dot"></span><svg class="ic"><use href="#i-close" /></svg></span>`;
    tab.querySelector(".label").textContent = f.name;
    tab.addEventListener("click", () => activate(path));
    tab.addEventListener("contextmenu", (e) => {
      e.preventDefault();
      openTabContextMenu(e.clientX, e.clientY, path);
    });
    tab.querySelector(".x").addEventListener("click", (e) => {
      e.stopPropagation();
      closeFile(path);
    });
    tab.addEventListener("dragstart", (e) => {
      dragSrcPath = path;
      tab.classList.add("dragging");
      e.dataTransfer.effectAllowed = "move";
    });
    tab.addEventListener("dragend", () => {
      dragSrcPath = null;
      tab.classList.remove("dragging");
      tabsEl.querySelectorAll(".tab").forEach(t => t.classList.remove("drag-over"));
    });
    tab.addEventListener("dragover", (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = "move";
      tab.classList.add("drag-over");
    });
    tab.addEventListener("dragleave", () => tab.classList.remove("drag-over"));
    tab.addEventListener("drop", (e) => {
      e.preventDefault();
      tab.classList.remove("drag-over");
      if (!dragSrcPath || dragSrcPath === path) return;
      const entries = [...openFiles.entries()];
      const srcIdx = entries.findIndex(([p]) => p === dragSrcPath);
      const dstIdx = entries.findIndex(([p]) => p === path);
      if (srcIdx < 0 || dstIdx < 0) return;
      const [moved] = entries.splice(srcIdx, 1);
      entries.splice(dstIdx, 0, moved);
      openFiles.clear();
      for (const [p, v] of entries) openFiles.set(p, v);
      renderTabs();
    });
    tabsEl.appendChild(tab);
  }
}

// ---- file tree ----
let rootPath = null;
let workspaceRoots = [];
const collapsedWorkspaceRoots = new Set();
const expandedTreeDirs = new Set();

function _treePath(path) {
  return _normalizeFsPath(String(path || "")).replace(/\/+$/, "");
}

function _treeRoots() {
  return workspaceRoots.length ? [...workspaceRoots] : (rootPath ? [rootPath] : []);
}

function _pruneExpandedTreeDirs() {
  const roots = _treeRoots();
  for (const path of [...expandedTreeDirs]) {
    if (!roots.some((root) => _pathIsAtOrUnder(path, root))) expandedTreeDirs.delete(path);
  }
}

function _treeDropRenderedDescendants(path, includeSelf = false) {
  path = _treePath(path);
  if (!path) return;
  for (const key of [...dirNodes.keys()]) {
    if (key === path) {
      if (includeSelf) dirNodes.delete(key);
      continue;
    }
    if (key.startsWith(path + "/")) dirNodes.delete(key);
  }
}

function _treeDropExpansionDescendants(path, includeSelf = false) {
  path = _treePath(path);
  if (!path) return;
  for (const key of [...expandedTreeDirs]) {
    if (key === path) {
      if (includeSelf) expandedTreeDirs.delete(key);
      continue;
    }
    if (key.startsWith(path + "/")) expandedTreeDirs.delete(key);
  }
}

function _treeMoveExpansionSubtree(fromPath, toPath) {
  fromPath = _treePath(fromPath);
  toPath = _treePath(toPath);
  if (!fromPath || !toPath || fromPath === toPath) return;
  const moves = [];
  for (const key of [...expandedTreeDirs]) {
    if (key === fromPath || key.startsWith(fromPath + "/")) {
      moves.push([key, toPath + key.slice(fromPath.length)]);
    }
  }
  for (const [oldPath, nextPath] of moves) {
    expandedTreeDirs.delete(oldPath);
    expandedTreeDirs.add(nextPath);
  }
}

function _treeSetExpanded(path, expanded) {
  path = _treePath(path);
  if (!path || workspaceRoots.includes(path)) return;
  if (expanded) expandedTreeDirs.add(path);
  else expandedTreeDirs.delete(path);
}

function _treeIsExpanded(path) {
  return expandedTreeDirs.has(_treePath(path));
}

function _treeLoadedNode(path) {
  return dirNodes.get(_treePath(path)) || null;
}

function _treeVisibleAncestor(path) {
  let current = parentDir(_treePath(path)).replace(/\/+$/, "");
  const roots = _treeRoots();
  while (current) {
    if (dirNodes.has(current) || roots.includes(current)) return current;
    const next = parentDir(current).replace(/\/+$/, "");
    if (!next || next === current) break;
    current = next;
  }
  return "";
}

function _treeReloadTargetForDir(dir) {
  dir = _treePath(dir);
  if (!dir || !rootPath) return "";
  const roots = _treeRoots();
  if (!roots.some((root) => dir === root || _pathIsAtOrUnder(dir, root))) return "";
  if (roots.includes(dir) || dirNodes.has(dir)) return dir;
  return _treeVisibleAncestor(dir) || roots.find((root) => _pathIsAtOrUnder(dir, root)) || rootPath || "";
}

// Normalize a filesystem path to forward slashes. Windows dialogs / read_dir return
// `C:\a\b`, but ALL path logic here joins & compares with "/" (rootPath + "/" + rel,
// startsWith(rootPath + "/"), split("/")…). A backslash root then matches NOTHING →
// relative paths don't resolve to the workspace ("不看当前工作目录"). Windows accepts
// "/" in paths, so posix-normalizing at every boundary makes it all consistent.
// No-op on macOS/Linux (they have no backslashes in paths).
function _toPosix(p) { return typeof p === "string" ? p.replace(/\\/g, "/") : p; }

function _normalizeFsPath(path) {
  if (typeof path !== "string") return path;
  // A filesystem name may legally end in whitespace on POSIX. Trimming the whole
  // path turns `/repo/name ` into a different file (`/repo/name`) and defeats the
  // invisible-whitespace recovery used by read_file. Call sites validate empty
  // model arguments separately; path normalization itself must preserve identity.
  let value = _toPosix(path);
  if (!value) return value;
  let prefix = "";
  if (/^[A-Za-z]:\//.test(value)) {
    prefix = value.slice(0, 2) + "/";
    value = value.slice(3);
  } else if (value.startsWith("//")) {
    prefix = "//";
    value = value.replace(/^\/+/, "");
  } else if (value.startsWith("/")) {
    prefix = "/";
    value = value.replace(/^\/+/, "");
  }
  const parts = [];
  for (const part of value.split("/")) {
    if (!part || part === ".") continue;
    if (part === "..") {
      if (parts.length && parts[parts.length - 1] !== "..") parts.pop();
      else if (!prefix) parts.push(part);
      continue;
    }
    parts.push(part);
  }
  return prefix + parts.join("/");
}

function _isAbsoluteFsPath(path) {
  const normalized = _normalizeFsPath(String(path || ""));
  return !!normalized && (normalized.startsWith("/") || normalized.startsWith("//") || /^[A-Za-z]:\//.test(normalized));
}

function _pathIdentity(path) {
  const normalized = _normalizeFsPath(path);
  const remoteCaseInsensitive = _remote.active && /windows|darwin|mac(?:os)?/i.test(_remote.platform || "");
  const localCaseInsensitive = !_remote.active && typeof navigator !== "undefined"
    && /Mac|Win/i.test((navigator.platform || "") + " " + (navigator.userAgent || ""));
  return typeof normalized === "string" && (remoteCaseInsensitive || localCaseInsensitive || /^[A-Za-z]:\//.test(normalized) || normalized.startsWith("//"))
    ? normalized.toLowerCase()
    : normalized;
}

function _pathIsAtOrUnder(candidate, parent) {
  const childIdentity = _pathIdentity(candidate);
  const parentIdentity = _pathIdentity(parent);
  if (!childIdentity || !parentIdentity) return false;
  return childIdentity === parentIdentity
    || childIdentity.startsWith(parentIdentity.endsWith("/") ? parentIdentity : parentIdentity + "/");
}

function _coherentFilePath(path) {
  const normalized = _normalizeFsPath(path);
  if (typeof normalized !== "string") return normalized;
  const identity = _pathIdentity(normalized);
  for (const known of openFiles.keys()) if (_pathIdentity(known) === identity) return known;
  for (const known of projectModels) if (_pathIdentity(known) === identity) return known;
  if (typeof _openingFiles !== "undefined") {
    for (const known of _openingFiles.keys()) if (_pathIdentity(known) === identity) return known;
  }
  return normalized;
}

// Wire the real LSP client now that workspace state exists. Disabled in the
// plain-browser mock (no real servers to talk to). Providers are registered for
// the "gap" languages Monaco's bundled service does not cover.
lspManager = createLspManager({
  backend,
  enabled: inTauri,
  getWorkspaceRoots: () => (workspaceRoots.length ? workspaceRoots : rootPath ? [rootPath] : []),
  showToast: (msg) => showToast(msg),
  showNotification: ({ title, message, actionLabel, duration, installCmd }) => {
    const toolName = (title || "").replace(/^缺少\s*/, "").replace(/\s*语言服务器$/, "") || "LSP";
    showNotification({
      title, message, actionLabel, duration,
      action: installCmd ? async () => {
        await openTerminal();
        writeToActiveTerminal(installCmd + "\n");
        _showInstallProgress(installCmd, toolName);
      } : undefined,
    });
  },
  onStatus: () => updateLspStatusBar(),
  onLog: (lang, line) => lspLogSink(lang, line),
});
lspManager.onCompletionSymbols = (symbols) => {
  _updateDynamicKeywords(symbols);
};
lspManager.registerProviders();

let _envLoadTimer = null;
let _modApiTimer = null;

const _idleRun = (fn) => (window.requestIdleCallback || ((f) => setTimeout(f, 30)))(fn);
function _onFileOpened(model) {
  if (!model) return;
  // Defer identifier extraction so it runs AFTER the file paints — never block the open.
  _idleRun(() => _extractFileIdentifiers(model));
  const langId = model.getLanguageId();

  const importedMods = _extractImportedModules(model);
  if (importedMods.length > 0) {
    setTimeout(() => _loadModuleApisOnly(importedMods), 200);
  }

  if (_envLoadTimer) clearTimeout(_envLoadTimer);
  _envLoadTimer = setTimeout(() => _loadEnvSymbols(langId), 1500);
}

monacoEditor.onDidChangeModel(() => {
  const model = monacoEditor.getModel();
  if (model) {
    _idleRun(() => _extractFileIdentifiers(model)); // deferred — don't block tab switches on big files
    if (_modApiTimer) clearTimeout(_modApiTimer);
    _modApiTimer = setTimeout(() => _refreshModuleApis(model), 2000);
  }
});

let _fileIdRefreshTimer = null;
monacoEditor.onDidChangeModelContent(() => {
  if (_fileIdRefreshTimer) clearTimeout(_fileIdRefreshTimer);
  _fileIdRefreshTimer = setTimeout(() => {
    const model = monacoEditor.getModel();
    if (model) {
      _extractFileIdentifiers(model);
      _refreshModuleApis(model);
    }
  }, 5000);
});

const lspLogBuffers = new Map();
function lspLogSink(lang, line) {
  let buf = lspLogBuffers.get(lang);
  if (!buf) {
    buf = [];
    lspLogBuffers.set(lang, buf);
  }
  buf.push(line);
  if (buf.length > 400) buf.shift();
  console.log(`[LSP:${lang}] ${line}`);
  document.dispatchEvent(new CustomEvent("lsp-log", { detail: { lang } }));
}

function updateLspStatusBar() {
  if (!lspManager) return;
  const all = lspManager.status();
  const ready = all.filter((s) => s.initialized).map((s) => s.lang);
  const starting = all.filter((s) => !s.initialized).map((s) => s.lang);
  if (ready.length || starting.length) {
    const parts = [];
    if (ready.length) parts.push(ready.join(", "));
    if (starting.length) parts.push(`(${starting.join(",")} starting…)`);
    setStatusBarItem(
      "lsp",
      { text: `LSP: ${parts.join(" ")}`, tooltip: `Active: ${ready.join(", ") || "none"}\nStarting: ${starting.join(", ") || "none"}\nClick for logs` },
      () => openFeaturePanel("lsp"),
    );
  } else {
    removeStatusBarItem("lsp");
  }
}

// Wire the real debug adapter client.
dapManager = createDapManager({
  backend,
  getWorkspaceRoots: () => (workspaceRoots.length ? workspaceRoots : rootPath ? [rootPath] : []),
  getAllBreakpoints,
  runInTerminal: (args) => debugRunInTerminal(args),
  showToast: (msg) => showToast(msg),
  callbacks: {
    onState: () => refreshDebugUI(),
    onOutput: (cat, text) => appendDebugConsole(cat, text),
    onShowLocation: (path, line) => showDebugLocation(path, line),
    onStopped: () => { showDebugDock(); refreshDebugUI(); }, // console dock + sidebar/toolbar; NOT the modal
    onContinued: () => { clearDebugLocation(); refreshDebugUI(); }, // running → step buttons disable
    onTerminated: () => { clearDebugLocation(); markDebugDockEnded(); updateDebugStatusBar(); },
  },
});

async function debugRunInTerminal(args) {
  await openTerminal();
  const parts = args?.args || [];
  if (!parts.length) return;
  const cmd = parts.map((p) => shellQuote(String(p))).join(" ");
  const cd = args.cwd ? `cd ${shellQuote(args.cwd)} && ` : "";
  writeToActiveTerminal(`\n${cd}${cmd}\n`);
}

function updateDebugStatusBar() {
  if (!dapManager) return;
  if (dapManager.isActive()) {
    const state = dapManager.isStopped() ? "paused" : "running";
    setStatusBarItem(
      "debug",
      { text: `Debug: ${state}`, tooltip: "点击查看调试面板" },
      () => showDebugDock(),
    );
  } else {
    removeStatusBarItem("debug");
  }
}

function iconSvg(id, cls = "") {
  return `<svg class="ic ${cls}"><use href="#${id}" /></svg>`;
}

// Real file-type icons from the Material Icon Theme (MIT-licensed), vendored as
// static SVGs under ./assets/file-icons and bundled by Vite (offline-capable in
// both the browser and the native Tauri app).
const ICON_URLS = import.meta.glob("./assets/file-icons/*.svg", {
  eager: true,
  query: "?url",
  import: "default",
});
function iconUrl(base) {
  return ICON_URLS[`./assets/file-icons/${base}.svg`] || "";
}
/** Render a bundled icon URL as an <img>, falling back to a generic glyph. */
function iconImg(url, cls = "") {
  if (!url) return iconSvg("i-file", "ic--doc");
  return `<img class="ic ${cls}" src="${url}" alt="" draggable="false" />`;
}

