function _pickCheapModel(currentId = "") {
  return currentId || "";
}
// Lexical fallback ranking over the curated catalog + MCP tools.
function _lexicalRank(text, k) {
  const cat = _relevantTools(text, k);
  const t = (text || "").toLowerCase();
  const words = t.split(/[\s,。，、:;:]+/).filter((w) => w.length >= 3);
  const mcp = _mcpCatalogEntries().map((e) => {
    const hay = (e.name + " " + e.desc).toLowerCase(); let s = 0;
    for (const w of words) if (hay.includes(w)) s += 1;
    return { e, s };
  }).filter((x) => x.s > 0).sort((a, b) => b.s - a.s).slice(0, 2).map((x) => x.e);
  const seen = new Set(); const merged = [];
  for (const x of [...cat, ...mcp]) { if (!seen.has(x.name)) { seen.add(x.name); merged.push(x); } }
  return merged.slice(0, k);
}
const _toolRankCache = new Map(); // taskKey -> ordered [{name,desc}]
// (A·semantic) RAG-MCP-style retrieval: a CHEAP model reads the task + every tool's
// one-liner and returns the most relevant tools by NAME — it understands INTENT (not
// just keywords), handles indirect/tricky tasks, and covers MCP tools. Cached per
// task; 3.5s-bounded; lexical fallback on miss/timeout/garbage.
async function _semanticToolRank(text, config) {
  const catalog = [..._TOOL_CATALOG.map((t) => ({ name: t.name, desc: t.desc })), ..._mcpCatalogEntries()];
  const key = String(text || "").slice(0, 160).toLowerCase() + "|" + catalog.length;
  if (_toolRankCache.has(key)) return _toolRankCache.get(key);
  const lexical = _lexicalRank(text, 6);
  try {
    const cheap = _pickCheapModel(config && config.model);
    if (!cheap) return lexical;
    const list = catalog.map((t, i) => `${i + 1}. ${t.name} — ${t.desc}`).join("\n");
    const prompt = `用户的任务：\n${String(text).slice(0, 1200)}\n\n可用工具：\n${list}\n\n仔细想这个任务真正要做哪些事，从上面选出**最该用到的工具**（按相关度排序，最多 7 个）。只输出工具名、用逗号分隔，不要解释、不要编造清单外的名字。`;
    const out = await Promise.race([
      backend.aiComplete({ ...config, model: cheap }, [{ role: "user", content: prompt }], 100),
      new Promise((res) => setTimeout(() => res(""), 3500)),
    ]);
    const names = String(out || "").split(/[,，\n、]+/).map((s) => s.replace(/^[-*\d.\s)）]+/, "").replace(/[（(].*$/, "").trim()).filter(Boolean);
    const lc = new Map(catalog.map((t) => [t.name.toLowerCase(), t]));
    const picked = [];
    for (const n of names) {
      const nl = n.toLowerCase();
      let hit = lc.get(nl) || catalog.find((t) => t.name.toLowerCase().split(" / ")[0] === nl);
      if (!hit) { const canon = _canonicalToolName(n); if (canon) hit = catalog.find((t) => t.name.toLowerCase().includes(canon)); }
      if (!hit) hit = catalog.find((t) => t.name.toLowerCase().includes(nl) && nl.length >= 4);
      if (hit && !picked.includes(hit)) picked.push(hit);
      if (picked.length >= 7) break;
    }
    // Prose-reply fallback: if the model didn't return a clean list, scan the whole
    // reply for any tool name appearing in it, in order of first mention.
    if (picked.length < 2) {
      const low = String(out || "").toLowerCase();
      const withPos = catalog.map((t) => ({ t, pos: low.indexOf(t.name.toLowerCase().split(" / ")[0]) }))
        .filter((x) => x.pos >= 0).sort((a, b) => a.pos - b.pos);
      for (const x of withPos) { if (!picked.includes(x.t)) picked.push(x.t); if (picked.length >= 7) break; }
    }
    const result = picked.length >= 2 ? picked : lexical;
    if (_toolRankCache.size > 60) _toolRankCache.clear();
    _toolRankCache.set(key, result);
    return result;
  } catch { return lexical; }
}
// (A) Build the task-start tool spotlight. Profile-driven priorities are primary:
// the base decides by task shape and live-evidence needs first, then semantic/MCP
// and lexical keyword retrieval only fill gaps.
async function _buildToolHint(text, config) {
  const profile = _engineeringTaskProfile(text);
  const profileRel = _profileToolPriorities(text, profile, 8);
  const lexical = _relevantTools(text, 6);
  const mcpCount = (_mcpToolCache || []).length;
  const warrants = mcpCount > 0 || (profileRel.length < 3 && lexical.length < 3);
  let semantic = [];
  if (warrants) { try { semantic = await _semanticToolRank(text, config); } catch { semantic = []; } }
  const rel = _mergeToolPriorityLists(profileRel, semantic, lexical).slice(0, 8);
  if (!rel || rel.length < 2) return "";
  return "\n\n🔧 **针对这个任务，优先想到这些工具**（全部工具仍可用，这是按任务画像和真实证据需求挑出的，别只盯着读写文件）：\n"
    + rel.map((t) => `- ${t.name}：${t.desc}`).join("\n");
}
// (B) Anti-forgetting refresh: a compact full catalog re-surfaced mid-run at the
// context tail, so advanced tools don't fade out of attention over a long task.
function _toolReminderBlock() {
  let s = "📋（提醒，继续当前任务即可）别忘了你手上这套**全工具**，按需取用、别只用读写跑命令：\n"
    + "· 代码：search(找定义/用法) · edit_file/multi_edit · write_file · find_files\n"
    + "· 验证：run_cmd(构建/测试) · get_diagnostics(看报错)\n"
    + "· Git：git_status/git_diff/git_log/git_blame 先看真实改动；git_commit/git_branch/git_push/git_pull/gh_pr_* 做提交、分支、远端和 PR/CI\n"
    + "· 联网：web_search(查文档/解法) · web_fetch(读全文) · http_request(调API)\n"
    + "· 网页/视觉：browser(测UI/点按钮/抓数据) · screenshot(看渲染) · generate_image(生成配图/头像/logo/UI设计稿)\n"
    + "· 🎨 **UI设计三件套**（做界面/设计/做APP时必用）：style_wardrobe(衣橱·整站风格选择·交互式·用户选完返回tokens) → design_board(设计看板·多方向对比·交互式·用户选方向后返回结果) → preview_choices(功能柜·组件级方案对比·实时预览·用户选完返回结果)\n"
    + "· 数据：db_query(mysql/postgres/sqlite/mssql/mongodb/redis/clickhouse/elastic)\n"
    + "· 容器/部署：用 run_cmd/run_in_terminal 跑 docker/compose/k8s/devcontainer 命令，read_logs/read_terminal/http_request 验证容器日志、端口和健康检查\n"
    + "· 持续/交互：run_in_terminal(启动 dev server/watch/守护进程) · read_logs/read_terminal/list_terminals/stop_terminal(看日志/停服务) · background_monitor(等端口/URL/文件/命令/抓包/人工操作后自动继续)\n"
    + "· 提效：run_worker(**并行**改多文件/**并行**生成衣橱3套风格) · run_subagent(大范围调研) · worktree(best-of-N 隔离工作树·难任务出多候选选最优) · generate_wiki(把代码库/产品自动摸成结构化产品Wiki存盘·做官网前打底) · update_plan · remember · lsp_definition/references";
  const mcp = _mcpCatalogEntries();
  if (mcp.length) s += "\n· 外接(MCP)：" + mcp.slice(0, 8).map((e) => e.name).join(" · ");
  return s;
}

// Per-turn "old hand" operating frame. This is deliberately dynamic and compact:
// it gives the model a decision law for THIS task instead of bloating the global
// prompt with one-size-fits-all commandments. The actual enforcement still lives
// in the loop gates below (plan/verify/UI/honesty/stuck recovery); this block makes
// the first move smarter so those gates become guardrails, not the main driver.
function _agentDecisionFrameBlock(text, profile = _engineeringTaskProfile(text)) {
  const t = String(text || "").replace(/\s+/g, " ").trim();
  if (!t) return "";
  const p = profile || {};
  const lines = [
    "\n\n🧭 **本轮老手决策框架（不要复述给用户，按它行动）**",
    "1. 先定终态：用户要的是回答、调查、改代码、运行/打包、UI、抓包/浏览器、实时数据，还是外部动作；不要把背景当任务。",
    "2. 工具前先内部过三问：当前假设是什么；下一步工具要验证/排除什么；如果结果不符合预期，下一步改用哪条证据路径。这个思考只指导行动，不刷思考卡、不写给用户看。",
    "3. 找证据缺口：缺路径→find_files/search/list_dir；缺真实内容→read_file；缺符号/调用方→find_symbol/lsp_references；缺运行状态→优先 get_diagnostics/read_logs/list_terminals/read_terminal 读现成错误与日志，再按需 run_cmd/browser；缺依赖且 package/lockfile 已声明→直接 npm ci/install/pnpm install/yarn install/bun install 恢复环境；缺动态事实→专用结构化工具或真实接口。",
    "4. 够证据就动手：最多一次定位扫；目标文件/接口已确认后立刻 edit_file/multi_edit/write_file/run_cmd，不为“显得认真”重复读同一版本或反复搜索。",
    "5. 每一步按因果链闭环：观察到什么 → 判断说明什么 → 下一步最小动作。失败看 exit code/stderr/真实响应/工具恢复提示，换证据或修根因，不原地重试同一招。",
  ];
  if (p.projectEngineering || p.engineeringGrade || p.allProjectsEngineering || p.projectScope || p.architecture) {
    lines.push("项目工程律：所有项目任务默认工程级，不管大小都走最短可靠证据链。小改动=真实文件/诊断 → 最小改动 → 真实验证；项目级改动先建立项目地图（package/workspace、入口、脚本、服务、配置、CI、数据库、部署线索）、模块边界和现有约定，再动代码。");
    lines.push("变更半径律：动手前识别调用方、API/数据契约、状态/缓存/权限/跨服务影响；不全仓盲改，不一次性重写无关模块；按薄切片交付，每个切片都有可验证结果。验证矩阵按影响选择 unit/typecheck/lint/build/integration/e2e/contract/migration/smoke，命令输出和 exit code 才算证据。");
    lines.push("可维护升级律：任何项目默认要好维护、好升级：清晰目录/模块边界、配置/env 集中、类型/schema/接口明确、组件/服务可复用、扩展点可替换、测试与 README/用法说明齐全；禁止把业务规则、颜色、端口、密钥、路径和魔法值散落硬编码。");
  }
  if (p.promptRescue || p.vagueProjectRequest) {
    lines.push("烂提示词救援律：用户说不清、提示词垃圾或触发词缺失时，不要卡住也不要乱写；先从上下文/项目现状归纳真实目标，列少量默认假设和可反悔选择，按常识补齐业务、UI、数据、权限、错误态和验收清单，只在关键方向会完全改变结果时才问。");
  }
  if (p.industrialProject || p.largeProject || p.multiService || p.productionReadiness || p.allProjectsEngineering) {
    lines.push("工业级/大项目律：先按架构边界拆服务/模块/包/数据流/队列/缓存/外部依赖；跨 API/DB/消息/缓存/权限的改动必须核对契约、迁移兼容、回滚路径、feature flag/配置、日志/指标/告警和发布风险；不能只写代码不看运行面。");
  }
  if (p.businessLogic || p.businessRisk || p.featureCompleteness) {
    lines.push("业务逻辑律：先把业务对象、角色/租户/权限、主流程/异常流程、状态机、金额/库存/配额/佣金等业务不变量摸清；实现不能只满足 happy path，必须覆盖取消、退款、重复提交、超时、并发、历史数据和审计记录。");
    lines.push("功能完整性律：需求按原话建立验收清单，逐项映射到 UI/API/DB/后台任务/日志/权限/测试；写完要核对没有丢功能、丢字段、丢状态、丢空错加载态，不能交半成品。");
  }
  if (p.businessRisk || p.securityRisk) {
    lines.push("业务漏洞/滥用律：任何涉及权限、订单、支付、库存、优惠、积分、租户、资源归属的功能，都要检查越权/IDOR、重复提交、重放、金额篡改、库存超卖、幂等、并发竞态、限流和风控绕过；修复要给出可复现滥用路径和回归断言。");
  }
  if (p.architectureQuality) {
    lines.push("架构质量律：先确认分层、领域边界、依赖方向、模块职责和公共契约；发现耦合/技术债时按最小可迁移切片处理，保留兼容层和回滚点，不把业务规则散落进 UI、路由或工具函数。");
  }
  if (p.requiresPlan || p.substantial || p.debugProject || p.uiProject) {
    lines.push("真正要改多文件、重构架构或交付复杂实现时，先在脑内理清现状取证、契约/调用方、实现、边界/兼容、真实验证和交付标准，然后直接执行；update_plan 只是可选整理工具，不是门槛。只读诊断、日志读取、依赖恢复和验证命令先直接做。");
  }
  if (p.bug || p.debugProject) {
    lines.push("Bug 修复律：先复现/读取真实报错、日志、截图、诊断或失败命令；沿入口、数据流、状态机、异步时序、边界值和调用方契约定位根因；补最小补丁后重跑同一失败路径或最接近回归。");
    const ladder = (typeof _agentBugEvidenceLadderBlock === "function") ? _agentBugEvidenceLadderBlock(t, p) : "";
    if (ladder) lines.push(ladder);
  }
  if (p.database || p.databaseArchitecture || p.dataModel || p.persistence) {
    lines.push("数据库律：先分清是查数据、改 schema、补迁移、调索引、做缓存，还是处理持久化；先看现有表结构/ORM/迁移/调用方和真实数据，再决定动哪一层。前端 table/grid 只是界面，不是数据库表。需要真实数据时优先 db_query；只有用户明确要求执行写库或 SQL 时才动外部数据库。");
  }
  if (p.databaseOps) {
    lines.push("数据库工业律：按业务读写模式选择关系型/文档/键值缓存/搜索/向量库；落地时必须考虑事务隔离、唯一约束、索引、连接池、迁移/回填/回滚、备份恢复、冷热数据和 ORM 兼容，不同数据库不能用同一套拍脑袋 CRUD。");
  }
  if (p.containerOps) {
    lines.push("容器/部署律：容器不是只写 Dockerfile；要核对 Dockerfile/compose/k8s/devcontainer、环境变量与 secrets、端口映射、volume 持久化、网络/service dependency、healthcheck/readiness、日志输出、迁移启动顺序和本地 smoke 命令。");
  }
  if (p.git || p.gitCommit || p.gitPublish || p.gitSync || p.gitReview || p.gitBranching) {
    lines.push("Git 律：先确认仓库根，不在错目录 commit/push/pull；只读调查用 git_status/git_diff/git_log/git_blame。提交前先看 status+diff，明确暂存范围和提交信息；分支操作先看当前分支；push/pull 先确认 remote/upstream 和当前分支；PR/CI 用 gh_pr_view/gh_pr_checks/gh_actions_log 读真实状态。修复“commit/push/branch 按钮或页面”是 UI/代码任务，不等于真的执行 Git。");
  }
  if (p.ui || p.uiProject) {
    lines.push("UI/前端律：先读 README/package/src/data/assets/public/screenshots 等真实内容源；用项目现有组件优先，新增界面优先 shadcn/ui + Radix 语义组件，Tailwind palette/theme token 统一配色；构建后用真实浏览器桌面+手机视口验证布局、console/network 和关键交互。");
  }
  if (p.websiteDelivery) {
    lines.push("网站生产交付律：网站不是只摆好看页面；必须覆盖真实内容/文案/素材、路由/404/SEO metadata、表单提交/API 错误、加载/空/失败状态、性能基础、无障碍、桌面+手机浏览器验收和主要转化路径。");
  }
  if (p.longRunningRuntime || p.interactiveWait) {
    lines.push("持续任务律：会长期运行的 dev server/watch/守护进程用 run_in_terminal；随后 read_logs/read_terminal 看 URL/日志/退出状态；等待端口/URL/文件/命令/人工操作用 background_monitor，timeout 后先查真实状态再决定。run_cmd 只跑会结束的短命令。");
  }
  if (p.browserAutomation || p.capture) {
    lines.push("浏览器/抓包律：登录、点击、填表、E2E 用有头 browser；先 check/nodes，连续动作必须用 batch，一次跑完后用 assert/check 验证，别每步 screenshot；截图只做最终视觉验收或定位肉眼排版问题。找真实网页接口先 capture_start(mode:\"isolated_browser\") → browser navigate(fresh:true) → 真实操作 → capture_flows。任意桌面 App 才用 system，手动代理/后台监听用 background。301/302 先看 Location/cookie/最终 URL，不乱拼。");
  }
  if (p.needsReferences) {
    lines.push("外部知识律：稳定语法/本项目代码直接推理；版本、兼容、第三方 API、安全、最新技术或社区踩坑才查官方文档/源码/开发者社区。社区结果是线索，关键结论读原文并标明日期语义，缺日期保持 unknown。");
  }
  if (!p.requiresPlan && !p.substantial && !p.bug && !p.ui && !p.longRunningRuntime && !p.browserAutomation && !p.capture) {
    lines.push("小任务律：直接用最短证据链完成；能一两个工具搞定就别升级成长流程，完成后给结果和真实验证/未验证边界。");
  }
  return lines.join("\n");
}

function _uiDesignCraftBlock(text, profile = _engineeringTaskProfile(text)) {
  const p = profile || {};
  if (!(p.ui || p.uiProject)) return "";
  return `\n\n🎨 **前端设计工艺要求（UI/网页任务必须执行，不要复述）**
- 设计先行：先确认真实内容、目标用户、品牌调性、现有素材/截图/数据源；缺方向时用 style_wardrobe 给 2-4 套可选风格，用户已指定风格就直接落地，不要卡着问。
- 设计系统：先定义 tokens 再写页面。至少覆盖 --background/--foreground/--card/--muted/--primary/--accent/--border/--ring/--radius，并映射到 Tailwind theme/CSS variables；主色只选 1 个色系 + 1 个强调色 + 中性色(zinc/slate/neutral)，禁止到处随机 hex。
- 配色纪律：浅色避免死白一片，用 subtle gradient / tinted surface / border alpha 分层；深色用 #0f172a/#111827 级别，不用纯黑；按钮和重点信息必须有可读对比，危险/成功/警告色单独 token。
- 排版纪律：明确 display/heading/body/caption 四级；标题用 font-display 或项目已有字体，正文用 font-sans；使用 text-5xl/4xl/3xl/2xl、leading-tight/relaxed、max-w-prose/measure 控制阅读宽度，禁止整页同字号同字重。
- 布局纪律：移动优先；container 用 mx-auto max-w-7xl px-4 sm:px-6 lg:px-8；section 用 py-16/24；复杂区块用 grid-cols-12 或 auto-fit card grid；gap-6/8/12，避免挤、平、乱。先信息架构后装饰：Hero → credibility/social proof → feature/use-case → detail/demo → CTA → footer。
- 组件纪律：优先 shadcn/ui + Radix primitives：Button/Card/Badge/Tabs/Accordion/Dialog/Sheet/Popover/Tooltip/Progress/Avatar/Separator/Skeleton；用 cn()/variant 思路统一 size、tone、state，别裸 div 造按钮/弹窗/进度条。
- 交互状态：每个可点击元素要有 hover/focus-visible/active/disabled/loading；表单要有 empty/error/success；图片/图标失败要有 fallback；动画短、克制、有目的。
- 实现纪律：先复用项目现有组件和样式约定；从零建前端优先 web_scaffold；大段 UI 不要把所有东西塞一个文件，按 section/component/data 拆；Tailwind 类名要围绕 tokens 和组件语义，不堆无法维护的魔法数。
- 视觉验收：构建通过不等于好看。启动真实 dev server 后，用 browser fresh 打开真实 URL；先 check/nodes，用 batch 连续完成交互，再用 assert/check 证明动作生效；只在最终视觉验收时分别截 1440x900 和 390x844 两张图检查首屏层级、间距、横向溢出、字体截断、console/network。截图丑就继续迭代一轮再收尾。`;
}

// ============================================================================
//  Experiential memory (ExpeL + AWM + Reflexion; "From Storage to Experience"
//  survey 2026). The agent had SEMANTIC memory (the `remember` fact-KG); this adds
//  the two missing types so it LEARNS ACROSS RUNS instead of starting cold:
//   • EPISODIC — a record of each past task (trajectory + outcome), per workspace.
//   • PROCEDURAL — a distilled, reusable insight per episode (Reflection→Experience).
//  At a new task we RETRIEVE the most similar past episodes and inject them as
//  guidance (ExpeL's few-shot-from-experience), so it gets better at THIS project.
// ============================================================================
const _EPISODE_STORE = "memory-episodes.json";
const _EP_STOP = new Set(["the","a","an","to","of","in","on","for","and","or","is","it","this","that","with","my","me","please","help","我","你","的","了","把","给","帮","一下","一个","这个","那个","请","让","和","与","怎么","如何","需要","想","要","现在","然后","看看","就是","可以"]);
function _epKey(root) { return "michael-ide.episodes:" + (root || "_global"); }
function _epLoad(root) { try { return JSON.parse(localStorage.getItem(_epKey(root)) || "[]") || []; } catch { return []; } }
function _epSave(root, eps) {
  if (eps.length > 120) eps = eps.slice(-120);
  try { localStorage.setItem(_epKey(root), JSON.stringify(eps)); } catch (e) { console.warn("[ep] local save failed:", e); }
  if (inTauri) (async () => { try { const s = await loadStore(_EPISODE_STORE); await s.set("ep:" + (root || "_global"), eps); await s.save(); } catch (e) { console.warn("[ep] file mirror failed:", e); } })();
}
async function _epSyncFromStore(root) {
  if (!inTauri) return;
  try {
    const s = await loadStore(_EPISODE_STORE);
    const fileEps = await s.get("ep:" + (root || "_global"));
    const local = _epLoad(root);
    if (Array.isArray(fileEps) && fileEps.length > local.length) { try { localStorage.setItem(_epKey(root), JSON.stringify(fileEps)); } catch {} }
    else if (local.length > (Array.isArray(fileEps) ? fileEps.length : 0)) { _epSave(root, local); }
  } catch {}
}
// Tokenize a task for similarity. ASCII → whole words; CJK has no word boundaries →
// character BIGRAMS (sliding 2-grams), the standard segmenter-free trick for Chinese
// overlap (so "登录页面" and "登录页" actually match on 登录/录页…).
function _taskWords(s) {
  const out = new Set();
  const text = String(s || "").toLowerCase();
  for (const w of text.replace(/[^\p{L}\p{N}\s]/gu, " ").split(/\s+/)) {
    if (/^[a-z0-9_]{2,}$/.test(w) && !_EP_STOP.has(w)) out.add(w);
  }
  for (const run of text.replace(/[^一-鿿]+/g, " ").split(/\s+/)) {
    if (run.length < 2) continue;
    for (let i = 0; i < run.length - 1; i++) { const bg = run.slice(i, i + 2); if (!_EP_STOP.has(bg)) out.add(bg); }
  }
  return out;
}
function _taskSim(aWords, b) {
  const bw = _taskWords(b); if (!aWords.size || !bw.size) return 0;
  let inter = 0; for (const w of aWords) if (bw.has(w)) inter++;
  return inter / Math.sqrt(aWords.size * bw.size); // cosine-ish over content words
}
function _retrieveEpisodes(task, root, k) {
  const eps = _epLoad(root); if (!eps.length) return [];
  const tw = _taskWords(task); if (!tw.size) return [];
  // Match on the past TASK (ExpeL: retrieve similar past tasks). 0.14 cleanly
  // separates real matches (≥~0.15) from unrelated ones (~0) given bigram tokens.
  return eps.map((e) => ({ e, s: _taskSim(tw, e.task || "") }))
    .filter((x) => x.s >= 0.14).sort((a, b) => b.s - a.s).slice(0, k || 3).map((x) => x.e);
}
// (Retrieve+inject) experiential guidance at task start — placed at the END of the
// message (recency slot) like the tool hint.
function _episodeHintBlock(task, root) {
  const rel = _retrieveEpisodes(task, root, 3);
  if (!rel.length) return "";
  const lines = rel.map((e) => {
    const tag = e.outcome === "failed" ? "⚠️坑" : e.outcome === "partial" ? "△" : "✓";
    return ("- " + tag + "「" + String(e.task || "").slice(0, 40) + "」：" + (e.insight || e.approach || "")).slice(0, 220);
  });
  return "\n\n📚 **这个项目里你做过的类似任务（经验参考，以当前实际为准、别生搬）**：\n" + lines.join("\n");
}
// (Store+reflect) at run end: persist the episode (Storage) and distill a reusable
// insight (Reflection→Experience; for a FAILED run, a Reflexion "what to avoid").
async function _recordEpisode(run, task, root, outcome, config) {
  try {
    if (!task || !run || !Array.isArray(run.recording) || run.recording.length < 2) return; // skip trivial
    const steps = run.recording;
    const files = [...new Set(steps.filter((s) => /write|edit|multiedit/.test(s.type))
      .map((s) => String(s.label || "").replace(/^(写入|编辑|改)\s*/, "")).filter(Boolean))].slice(0, 8);
    const ep = {
      id: "ep_" + Math.random().toString(36).slice(2, 9), ts: (new Date()).toISOString().slice(0, 19),
      task: String(task).slice(0, 160), outcome, steps: steps.length, files,
      approach: steps.slice(0, 12).map((s) => s.label).filter(Boolean).join(" → ").slice(0, 280), insight: "",
    };
    const eps = _epLoad(root); eps.push(ep); _epSave(root, eps); // Storage stage (immediate)
    // Reflection→Experience: distill ONE transferable insight via a cheap model.
    const cheap = _pickCheapModel(config && config.model);
    const stepList = steps.map((s) => (s.ok ? "✓ " : "✗ ") + s.label).join("\n").slice(0, 1800);
    const prompt = `这是 AI 编码助手刚完成的一个任务的动作记录。抽取**一条可复用经验**，让下次遇到同类任务更快更对。\n\n任务：${ep.task}\n结果：${outcome === "failed" ? "失败/未完成" : outcome === "partial" ? "部分完成" : "成功"}\n动作序列：\n${stepList}\n\n只输出**一句话**（≤60字）可迁移的经验：${outcome === "failed" ? "这类任务为什么没成/坑在哪 + 下次该怎么做。" : "这类任务在本项目里的有效套路/关键步骤/要注意什么。"}不要复述任务、不要客套。`;
    const out = await Promise.race([
      backend.aiComplete({ ...config, model: cheap }, [{ role: "user", content: prompt }], 120),
      new Promise((res) => setTimeout(() => res(""), 6000)),
    ]);
    const insight = String(out || "").trim().replace(/^["「『]+|["」』]+$/g, "").slice(0, 160);
    if (insight) { const cur = _epLoad(root); const i = cur.findIndex((x) => x.id === ep.id); if (i >= 0) { cur[i].insight = insight; _epSave(root, cur); } }
    // Procedural memory (AWM): if this success matches past successes, induce a workflow.
    try { await _maybeInduceWorkflow(ep, root, config); } catch {}
  } catch { /* best-effort learning — never break the run */ }
}

// ---- Procedural skill library (AWM — Agent Workflow Memory). Episodic insights are
// one-liners; this captures STRUCTURED, reusable WORKFLOWS for task TYPES that recur
// (Voyager's skill library, AWM's workflow induction). When a successful task matches
// past successful ones, induce/refine a named workflow {name, when, steps}; retrieve
// the matching workflow at task start as a proven recipe. Proven to lift completion. --
const _WORKFLOW_STORE = "memory-workflows.json";
function _wfKey(root) { return "michael-ide.workflows:" + (root || "_global"); }
function _wfLoad(root) { try { return JSON.parse(localStorage.getItem(_wfKey(root)) || "[]") || []; } catch { return []; } }
function _wfSave(root, wfs) {
  if (wfs.length > 40) wfs = wfs.slice(-40);
  try { localStorage.setItem(_wfKey(root), JSON.stringify(wfs)); } catch {}
  if (inTauri) (async () => { try { const s = await loadStore(_WORKFLOW_STORE); await s.set("wf:" + (root || "_global"), wfs); await s.save(); } catch {} })();
}
async function _wfSyncFromStore(root) {
  if (!inTauri) return;
  try {
    const s = await loadStore(_WORKFLOW_STORE);
    const file = await s.get("wf:" + (root || "_global"));
    const local = _wfLoad(root);
    if (Array.isArray(file) && file.length > local.length) { try { localStorage.setItem(_wfKey(root), JSON.stringify(file)); } catch {} }
    else if (local.length > (Array.isArray(file) ? file.length : 0)) { _wfSave(root, local); }
  } catch {}
}
function _retrieveWorkflow(task, root) {
  const wfs = _wfLoad(root); if (!wfs.length) return null;
  const tw = _taskWords(task); if (!tw.size) return null;
  const ranked = wfs.map((w) => ({ w, s: _taskSim(tw, (w.name || "") + " " + (w.when || "") + " " + (w.episodes || []).join(" ")) }))
    .filter((x) => x.s >= 0.16).sort((a, b) => b.s - a.s);
  return ranked.length ? ranked[0].w : null;
}
function _workflowHintBlock(task, root) {
  const w = _retrieveWorkflow(task, root);
  if (!w || !Array.isArray(w.steps) || !w.steps.length) return "";
  return "\n\n💡 **本项目里这类任务的成熟做法（工作流「" + (w.name || "") + "」，已复用 " + (w.uses || 1) + " 次，按需调整、别生搬）**：\n"
    + w.steps.map((s, i) => `${i + 1}. ${s}`).join("\n");
}
// AWM induction: a SUCCESSFUL task that recurs (≥1 similar past success) → induce or
// refine a reusable workflow from that cluster. Cheap, async, best-effort.
async function _maybeInduceWorkflow(currentEp, root, config) {
  try {
    if (!currentEp || currentEp.outcome !== "success") return;
    const tw = _taskWords(currentEp.task);
    const similar = _epLoad(root).filter((e) => e.id !== currentEp.id && e.outcome === "success" && _taskSim(tw, e.task || "") >= 0.16).slice(-3);
    if (!similar.length) return; // not a recurring pattern yet → no workflow
    const cluster = [currentEp, ...similar];
    const cheap = _pickCheapModel(config && config.model);
    const desc = cluster.map((e, i) => `任务${i + 1}：${e.task}\n做法：${e.approach || ""}`).join("\n\n");
    const prompt = `下面是同一类、都成功完成的几个编码任务及其做法。归纳出一个**可复用工作流**。\n\n${desc}\n\n严格输出 JSON（不要任何别的字）：{"name":"简短名称","when":"什么时候用(一句)","steps":["通用步骤1","步骤2"]}。步骤 3–6 条、要通用可迁移、写清用哪些工具。`;
    const out = await Promise.race([
      backend.aiComplete({ ...config, model: cheap }, [{ role: "user", content: prompt }], 300),
      new Promise((res) => setTimeout(() => res(""), 7000)),
    ]);
    const obj = _safeJsonLoose(out);
    if (!obj || !obj.name || !Array.isArray(obj.steps) || !obj.steps.length) return;
    const wf = {
      id: "wf_" + Math.random().toString(36).slice(2, 8), name: String(obj.name).slice(0, 40),
      when: String(obj.when || "").slice(0, 90), steps: obj.steps.slice(0, 8).map((s) => String(s).slice(0, 140)),
      episodes: cluster.map((e) => String(e.task).slice(0, 40)), uses: cluster.length, ts: currentEp.ts,
    };
    const wfs = _wfLoad(root);
    const exIdx = wfs.findIndex((x) => _taskSim(_taskWords(wf.name + " " + wf.when), (x.name || "") + " " + (x.when || "")) >= 0.4);
    if (exIdx >= 0) wfs[exIdx] = { ...wf, id: wfs[exIdx].id, uses: (wfs[exIdx].uses || 1) + 1 };
    else wfs.push(wf);
    _wfSave(root, wfs);
  } catch {}
}

function _recLabel(call) {
  const p = call._resolvedPath || call.path || "";
  switch (call.type) {
    case "read": return "读取 " + p;
    case "write": return "写入 " + p;
    case "edit": case "multiedit": return "编辑 " + p;
    case "cmd": case "termtask": return "运行  $ " + (call.command || "").slice(0, 70);
    case "search": return "搜索 “" + (call.query || "") + "”";
    case "find": return "查找 " + (call.query || call.pattern || "");
    case "web": return "抓取网页 " + (call.url || "");
    case "websearch": return "联网搜索 “" + (call.query || "") + "”";
    case "db": return "数据库(" + (call.driver || "") + ") " + (call.query || "").slice(0, 50);
    case "screenshot": return "截图";
    case "browser": return "浏览器 " + (call.action || "");
    case "genimage": return "生成图片 → " + (call.dest || "");
    case "subagent": return "子智能体调研：" + (call.description || "");
    case "worker": return "并行 worker：" + (call.description || "");
    case "delete": return "删除 " + p;
    case "move": return "移动 " + p;
    case "git": return "git " + (call.op || "");
    case "diag": return "诊断检查";
    case "think": return "思考";
    case "recall": return "回忆检索 “" + (call.query || "") + "”";
    case "debate": return "辩论：" + String(call.question || "").slice(0, 40);
    default: return call.type + (p ? " " + p : "");
  }
}

// Effect routing is local and deterministic. An earlier model-based intent router made
// a second network request before every Agent turn, adding latency and turning even a
// simple context message into an unnecessary online query.
function _effectTargetForTask(task, engineering = _engineeringTaskProfile(task)) {
  const text = String(task || "");
  if (engineering?.bug || engineering?.architecture || engineering?.ui
      || engineering?.databaseArchitecture || engineering?.dataModel || engineering?.persistence
      || /(?:代码|源码|文件|函数|组件|页面|模块|接口实现|\bcode\b|\bsource\b|\bfile\b|\bfunction\b|\bcomponent\b|\bmodule\b|\brefactor\b|\bfix\b)/i.test(text)) return "workspace";
  if (engineering?.git) return "external";
  if (/(?:github|gitlab|gitee|\bgit\b|pull request|\bpr\b|commit|push|pull|branch|仓库|提交|推送|分支|数据库|\bsql\b|部署|发布|上传|下载|自动化|远程|database|deploy|release|upload|download|automation|remote)/i.test(text)) return "external";
  if (/(?:编译|构建|打包|运行|启动|测试|安装依赖|compile|build|package|run|start|test|install)/i.test(text)) return "runtime";
  return engineering?.implementation ? "workspace" : "external";
}
// LLM 自省批判器（收尾把关）：不写死规则/阈值/正则——把「答得够不够深、任务真完成没有」
// 的判断交给一次独立的模型调用。它看到：用户任务、运行草稿纸（读过/改过/发现）、准备给出的
// 回答草稿，返回 {done, instruction}。不 done 时 instruction 是给智能体的针对性下一步指令。
// 失败/超时一律放行（fail-open），绝不因为批判器挂了卡死运行。
async function _wrapUpCritic({ config, task, padText, draft, readList }) {
  if (!config || !config.baseUrl || !config.apiKey) return null;
  const sys = '你是一个编码智能体的收尾评审。判断它现在收尾是否合格，只输出严格 JSON：{"done":true|false,"instruction":"<不合格时给它的具体下一步指令，一两句>"}。'
    + '评审标准：回答/工作要与用户任务的深度和范围匹配——问"项目是干嘛的/架构"这类全局理解题，必须基于真正读过入口和核心模块的源码，只读 README 或一两个文件就下结论=不合格；'
    + '改代码的任务，声称完成但没验证/没跑检查=不合格；答非所问、明显浅、留着没做完的事=不合格。'
    + '反之，简单问题简单答完全合格，别为难它、别要求过度工作。拿不准就放行(done=true)。只输出 JSON。';
  const user = `用户任务：${String(task || "").slice(0, 1200)}\n\n它读过的文件：${readList || "（无）"}\n\n运行进度（草稿纸）：\n${String(padText || "（空）").slice(0, 2000)}\n\n它准备给出的回答/收尾：\n${String(draft || "（无文字，直接结束）").slice(0, 3000)}`;
  try {
    const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
    const to = ctrl ? setTimeout(() => ctrl.abort(), 12000) : null;
    const res = await fetch(config.baseUrl.replace(/\/+$/, "") + "/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: "Bearer " + (config.apiKey || "") },
      body: JSON.stringify({ model: config.model, messages: [{ role: "system", content: sys }, { role: "user", content: user }], max_tokens: 220, temperature: 0, stream: false }),
      signal: ctrl ? ctrl.signal : undefined,
    });
    if (to) clearTimeout(to);
    if (!res.ok) return null;
    const data = await res.json();
    const j = _safeJsonLoose((data && data.choices && data.choices[0] && data.choices[0].message && data.choices[0].message.content) || "");
    if (!j || typeof j.done !== "boolean") return null;
    return { done: j.done, instruction: String(j.instruction || "").slice(0, 600) };
  } catch { return null; }
}


function _runRequiredEffect(run) {
  if (!run || run.mode !== "agent") return "inspect";
  if (run.engineering?.explicitMutation) return "mutate";
  if (run.engineering?.explicitReadOnly) return "inspect";
  if (run.engineering?.implementation && run.engineering?.applies) return "inspect";
  return run.engineering?.applies ? "mutate" : "answer";
}
function _runEffectTarget(run) {
  const text = [run?._originalText, run?._steeringText].filter(Boolean).join("\n");
  const engineering = { ..._engineeringTaskProfile(text), ...(run?.engineering || {}) };
  if (engineering.explicitWorkspaceMutation) return "workspace";
  if ((engineering.runtimeObligations || _runtimeObligationsForTask(text)).length) return "runtime";
  if ((engineering.externalObligations || _externalObligationsForTask(text)).length) return "external";
  return _effectTargetForTask(text, engineering);
}

function _requiredEffectContract(run) {
  const empty = { workspace: false, runtime: [], external: [] };
  if (!run || _runRequiredEffect(run) !== "mutate") return empty;
  const text = [run._originalText, run._steeringText].filter(Boolean).join("\n");
  const engineering = { ..._engineeringTaskProfile(text), ...(run.engineering || {}) };
  const cancelled = run._cancelledEffectKinds instanceof Set ? run._cancelledEffectKinds : new Set(run._cancelledEffectKinds || []);
  const runtime = Array.from(new Set([
    ...(engineering.runtimeObligations || _runtimeObligationsForTask(text)),
    ...(run._addedRuntimeObligations || []),
  ]))
    .filter((kind) => _RUNTIME_OBLIGATION_ORDER.includes(kind) && !cancelled.has(`runtime:${kind}`));
  const external = Array.from(new Set([
    ...(engineering.externalObligations || _externalObligationsForTask(text)),
    ...(run._addedExternalObligations || []),
  ]))
    .filter((kind) => _EXTERNAL_OBLIGATION_ORDER.includes(kind) && !cancelled.has(`external:${kind}`));
  const hasWorkspaceObject = !!(engineering.bug || engineering.architecture || engineering.ui || engineering.databaseArchitecture || engineering.dataModel || engineering.persistence)
    || /(?:代码|源码|文件|函数|组件|页面|模块|接口实现|\bcode\b|\bsource\b|\bfile\b|\bfunction\b|\bcomponent\b|\bmodule\b)/i.test(text);
  let workspace = !cancelled.has("workspace")
    && (!!engineering.explicitWorkspaceMutation || !!run._steeredWorkspaceRequired)
    && (!external.length || hasWorkspaceObject || !!run._steeredWorkspaceRequired);
  if (!workspace && !runtime.length && !external.length && cancelled.size === 0) {
    const fallback = _runEffectTarget({ ...run, engineering });
    // 纯信息询问（"这个项目干嘛用的"）没有副作用义务——别把它兜底成 external，
    // 否则收尾被"外部副作用"门反复卡住，模型只能一遍遍辩解、重复复述答案。
    if (fallback === "external" && _isInformationalQuery(text)) return empty;
    workspace = fallback === "workspace";
    if (fallback === "external") external.push("external");
    if (fallback === "runtime" && !runtime.length) runtime.push("run");
  }
  return { workspace, runtime, external };
}

// 纯信息询问：用户在"问"而不是"要求做"。只用于副作用兜底判定，带改动动词的任务
// 在到达兜底前就已按 bug/architecture/mutation 信号归类，不会走到这里。
function _isInformationalQuery(text) {
  const t = String(text || "").trim();
  if (!t) return false;
  const lastLine = t.split("\n").map((s) => s.trim()).filter(Boolean).pop() || t;
  return /[？?]\s*$/.test(lastLine)
    || /(?:是什么|干嘛|干什么|做什么|什么用|啥用|什么意思|怎么回事|介绍(?:一下|下)?|解释(?:一下|下)?|讲讲|说说|梳理(?:一下|下)?|总结(?:一下|下)?|了解(?:一下|下)?|what(?:'s| is| does)\b|explain\b|describe\b|tell me about|overview)/i.test(t);
}

function _missingRequiredEffects(run, evidence) {
  evidence = evidence || {};
  const contract = _requiredEffectContract(run);
  const completedRuntime = new Set(Array.isArray(evidence.runtimeEffects)
    ? evidence.runtimeEffects : evidence.runtimeEffects instanceof Set ? [...evidence.runtimeEffects] : []);
  const completedExternal = new Set(Array.isArray(evidence.externalEffects)
    ? evidence.externalEffects : evidence.externalEffects instanceof Set ? [...evidence.externalEffects] : []);
  const missing = [];
  if (contract.workspace && !(Number(evidence.workspaceOps) > 0)) missing.push("workspace");
  for (const kind of contract.runtime) if (!completedRuntime.has(kind)) missing.push(`runtime:${kind}`);
  for (const kind of contract.external) if (!completedExternal.has(kind)) missing.push(`external:${kind}`);
  return missing;
}

function _planEffectForRun(run) {
  if (_runRequiredEffect(run) !== "mutate") return "inspect";
  return _requiredEffectContract(run).workspace ? "mutate" : "execute";
}

function _callCanBypassPlanGate(call) {
  if (!call) return true;
  if (_isReadOnlyParallel(call)) return true;
  if (call.type === "cmd" || call.type === "termtask") {
    const command = String(call.command || "");
    return _looksLikeReadOnlyCommand(command)
      || _looksLikeVerificationCommand(command)
      || _isDependencyRestoreCommand(command)
      || _isBenignRunCommand(command);
  }
  if (call.type === "git" && !["commit", "push", "pull", "clone", "stash", "stash_pop"].includes(call.op)) return true;
  if (call.type === "db" && !_dbCallMayMutate(call)) return true;
  if (call.type === "http" && !_toolMayProduceExternalEffect(call)) return true;
  if (call.type === "automation" && !_toolMayProduceExternalEffect(call)) return true;
  if (call.type === "system" && !_toolMayProduceExternalEffect(call)) return true;
  return false;
}

function _runNeedsPlanGateNow(run, call = null) {
  return false;
}

function _requiredPlanIssue(run, steps, call = null) {
  return "";
}

