        runtimeEffects: [..._runtimeEffects],
        externalEffects: [..._externalEffects],
        finalErr: _formatAgentFinalError(finalErr),
        finalVerificationNote,
        hitCap,
        didMutate,
        didVerify,
        verificationPassed,
        uiVerificationPassed,
