      const _bmTypeLabels = { manual: "等用户确认", capture: "监控抓包", file: bmFilePat ? "等文件内容匹配" : "等文件出现", command: "等命令成功", url: "等 URL 可达", port: "等端口监听" };
      res.className = "atc-result atc-result--ok"; res.textContent = `⏳ ${bmMsg}`;
