                  if (_retry === 0) { await new Promise(r => setTimeout(r, 400)); continue; }
                  blog.push(`${i + 1}. ${op} ✗ ${String(e?.message || e).slice(0, 50)}（重试后仍失败，后续步骤已停）`); _batchBroken = true;
