// Figma 令牌存本机 localStorage（与 AI 网关配置解耦）；供 figma 工具读取。带「测试」按钮打 /v1/me。
let _figFieldBound = false;
function _initFigmaTokenField() {
  const input = $("figmaTokenInput"); if (!input) return;
  try { input.value = localStorage.getItem("michael-ide.figma-token") || ""; } catch {}
  if (_figFieldBound) return; _figFieldBound = true;
  const save = () => { try { localStorage.setItem("michael-ide.figma-token", input.value.trim()); } catch {} };
  input.addEventListener("change", save);
  input.addEventListener("blur", save);
  const testBtn = $("figmaTokenTest"), hint = $("figmaTokenHint");
  const hintDefault = hint ? hint.innerHTML : "";
  if (testBtn) testBtn.addEventListener("click", async () => {
    const tok = input.value.trim();
    if (!tok) { if (hint) hint.textContent = "先填入令牌再测试。"; return; }
    save();
    testBtn.disabled = true; const orig = testBtn.textContent; testBtn.textContent = "测试中…";
    try {
      let ok = false, who = "";
      if (inTauri && backend && backend.invoke) {
        const r = await backend.invoke("http_request", { method: "GET", url: "https://api.figma.com/v1/me", headers: { "X-Figma-Token": tok }, body: null, timeoutSecs: 20 });
        if (r && r.ok && r.body) { try { const j = JSON.parse(r.body); who = j.email || j.handle || ""; } catch {} ok = true; }
      } else {
        const r = await fetch("https://api.figma.com/v1/me", { headers: { "X-Figma-Token": tok } });
        if (r.ok) { const j = await r.json(); who = j.email || j.handle || ""; ok = true; }
      }
      if (hint) hint.textContent = ok ? `✅ 令牌有效${who ? "：" + who : ""}。figma 工具已就绪。` : "❌ 令牌无效或无权限，检查后重试。";
    } catch (e) { if (hint) hint.textContent = "❌ 测试失败：" + String(e && e.message || e).slice(0, 80); }
    finally { testBtn.disabled = false; testBtn.textContent = orig; if (hint && hintDefault) setTimeout(() => { if (hint.textContent.startsWith("✅") || hint.textContent.startsWith("❌")) hint.innerHTML = hintDefault; }, 6000); }
  });
}

