$("loginBackBtn")?.addEventListener("click", () => { _resetLoginUI(); $("loginEmail")?.focus(); });

$("loginSubmitBtn")?.addEventListener("click", async () => {
  const email = _loginEmail || $("loginEmail")?.value?.trim();
  const password = $("loginPassword")?.value || "";
  const code = $("loginCode")?.value?.trim() || "";
  const btn = $("loginSubmitBtn");
  try {
    if (_loginMode === "login") {
      if (!password) { $("loginPassword")?.focus(); return; }
      _finishLogin(await _withBtn(btn, t("login.loggingIn"), () => backend.authLogin(email, password)));
    } else if (_loginMode === "code-login") {
      if (code.length !== 6) { $("loginCode")?.focus(); return; }
      _finishLogin(await _withBtn(btn, t("login.verifying"), () => backend.authVerifyCode(email, code)));
    } else { // signup
      if (!_codeSent) {
        if (password.length < 6) { alert(t("login.passwordMin")); $("loginPassword")?.focus(); return; }
        const msg = await _withBtn(btn, t("login.sendingCode"), () => backend.authSendCode(email));
        _codeSent = true;
        const pw = $("loginPassword"); if (pw) pw.disabled = true;   // lock the chosen password
        _showCodeField(true);
        $("loginSubmitBtn").textContent = t("login.completeSignup");
        alert(msg);
      } else {
        if (code.length !== 6) { $("loginCode")?.focus(); return; }
        _finishLogin(await _withBtn(btn, t("login.signingUp"), () => backend.authRegister(email, password, code)));
      }
    }
  } catch (e) {
    alert(t("login.failed") + "：" + (e?.message || e));
  }
});

