function keyCombo(e) {
  const isMac = isMacPlatform();
  const parts = [];
  if ((isMac && e.metaKey) || (!isMac && e.ctrlKey)) parts.push("mod");
  if (e.ctrlKey && (isMac || e.metaKey)) parts.push("ctrl");
  if (e.metaKey && !isMac) parts.push("meta");
  if (e.shiftKey) parts.push("shift");
  if (e.altKey) parts.push("alt");
  const key = e.key.toLowerCase();
  if (!["control", "shift", "alt", "meta"].includes(key)) parts.push(key);
  return parts.join("+");
}

function keyComboAliases(e) {
  const combo = keyCombo(e);
  const aliases = [combo];
  // Back-compat: older Windows/Linux builds recorded/defaulted Ctrl shortcuts as
  // `ctrl+...`. The canonical cross-platform form is now `mod+...`, but trying
  // the legacy alias keeps existing saved bindings working.
  if (!isMacPlatform() && e.ctrlKey && !e.metaKey && combo.startsWith("mod+")) {
    aliases.push("ctrl+" + combo.slice(4));
  }
  return [...new Set(aliases.filter(Boolean))];
}

loadKeybindings().catch(console.error);

window.addEventListener("keydown", (e) => {
  const bindings = getKeybindings();
  const action = keyComboAliases(e).map((combo) => bindings[combo]).find(Boolean);
  if (action && KB_ACTIONS[action]) {
    e.preventDefault();
    e.stopPropagation();
    KB_ACTIONS[action]();
  }
});

